/* st_rerun_skeptic (Claude, own code): phase-seed tangent on the quiet reheating background.
 *
 * Background: Claude's OWN rp_reheating engine (tracks/rp_reheating/code/rpreheat.c, mode 0), included unchanged:
 *   H from the Friedmann constraint, Raychaudhuri Hdot from its d[16].
 * Tangent (this file, own formulation, not Codex's): physical cosmic-time perturbations of the six canonical reals
 *   phi = sqrt2 (Re X, Im X, Re Y, Im Y, Re S, Im S):
 *     dphi_tt = -3 H dphi_t - (k^2/a^2) dphi - (Hess V + xi R P_X) dphi,  R = 6 (Hdot + 2 H^2),
 *   Hess V generated by sympy from the potential (hess_own.h), no metric/inflaton perturbations, e = 0.
 * Integrator: Dormand-Prince 5(4) of the rp engine, but with a MAX-norm error over all components (not RMS),
 *   steps clipped to land on uniform output times.
 * Output (binary doubles per sample): t, a, H, N_X, R_trace, R_geom, then per k: amp, dN_X (unnormalised).
 */
#define main rp_original_main
#include "../../../rp_reheating/code/rpreheat.c"
#undef main
#include "hess_own.h"

static int NK; static double *KK;

static void full(const double *y, double *d) {
  rhs(y, d);
  geo g; geometry(y, &g);
  double a = exp(y[0]), H = g.H, Hd = d[16], Rg = 6 * (Hd + 2 * H * H);
  double f[6]; for (int i = 0; i < 6; i++) f[i] = sqrt(2.) * y[3 + i];
  double Hs[6][6]; hess_own(f, Hs);
  Hs[0][0] += xi * Rg; Hs[1][1] += xi * Rg;
  for (int m = 0; m < NK; m++) {
    const double *D = y + ND + 12 * m, *Dd = D + 6; double *o = d + ND + 12 * m;
    double kk = KK[m] * KK[m] / (a * a);
    for (int i = 0; i < 6; i++) {
      double s = 0; for (int j = 0; j < 6; j++) s += Hs[i][j] * D[j];
      o[i] = Dd[i];
      o[6 + i] = -3 * H * Dd[i] - kk * D[i] - s;
    }
  }
}

static void emit(FILE *out, double t, const double *y) {
  geo g; geometry(y, &g); double d[ND]; rhs(y, d);
  double a = exp(y[0]), a3 = a * a * a;
  double p0 = sqrt(2.) * y[3], p1 = sqrt(2.) * y[4], v0 = sqrt(2.) * y[9], v1 = sqrt(2.) * y[10];
  double rec[6] = {t, a, g.H, a3 * (p0 * v1 - p1 * v0), g.R, 6 * (d[16] + 2 * g.H * g.H)};
  fwrite(rec, sizeof(double), 6, out);
  for (int m = 0; m < NK; m++) {
    const double *D = y + ND + 12 * m, *Dd = D + 6;
    double r[2] = {(p0 * D[0] + p1 * D[1]) / (p0 * p0 + p1 * p1),
                   a3 * (D[0] * v1 + p0 * Dd[1] - D[1] * v0 - p1 * Dd[0])};
    fwrite(r, sizeof(double), 2, out);
  }
}

int main(int argc, char **argv) {
  if (argc != 3) { fprintf(stderr, "skeptic_tangent in.bin out.bin\n"); return 1; }
  FILE *in = fopen(argv[1], "rb"), *out = fopen(argv[2], "wb"); if (!in || !out) return 2;
  double pr[17]; if (fread(pr, sizeof(double), 17, in) != 17) return 3;
  MODE = 0; b = pr[0]; gam = pr[1]; xi = pr[2]; eta2 = pr[3]; cH = 0; lx = pr[4]; ly = pr[5]; ls = pr[6]; kap = pr[7];
  MM = pr[8]; hh = pr[9]; mu = pr[10]; double end = pr[11], rtol = pr[12], atol = pr[13], dtout = pr[14]; NK = (int)pr[15];
  int nvar = ND + 12 * NK; double *y = calloc(nvar, sizeof(double)); KK = calloc(NK, sizeof(double));
  for (int i = 0; i < 6; i++) if (fread(&y[3 + i], sizeof(double), 1, in) != 1) return 4;
  if (fread(KK, sizeof(double), NK, in) != (size_t)NK) return 5;
  double seed[6]; if (fread(seed, sizeof(double), 6, in) != 6) return 6;
  fclose(in); (void)pr[16];
  { cplx z[3]; double V; cplx F[3]; for (int i = 0; i < 3; i++) z[i] = y[3 + 2 * i] + I * y[4 + 2 * i]; potential(z, &V, F);
    double f = 1 - 2 * xi * eta2 * creal(z[0] * conj(z[0])); double need = 3 * f - eta2 * V;
    y[1] = sqrt(2 * need) / b; y[16] = 1.0; y[17] = 0.0; geo g; geometry(y, &g); KV0 = g.K + g.V; }
  for (int m = 0; m < NK; m++) for (int i = 0; i < 6; i++) { y[ND + 12 * m + i] = seed[i]; y[ND + 12 * m + 6 + i] = 0; }
  static const double a21 = 1. / 5, a31 = 3. / 40, a32 = 9. / 40, a41 = 44. / 45, a42 = -56. / 15, a43 = 32. / 9,
    a51 = 19372. / 6561, a52 = -25360. / 2187, a53 = 64448. / 6561, a54 = -212. / 729,
    a61 = 9017. / 3168, a62 = -355. / 33, a63 = 46732. / 5247, a64 = 49. / 176, a65 = -5103. / 18656,
    b1 = 35. / 384, b3 = 500. / 1113, b4 = 125. / 192, b5 = -2187. / 6784, b6 = 11. / 84,
    e1 = 71. / 57600, e3 = -71. / 16695, e4 = 71. / 1920, e5 = -17253. / 339200, e6 = 22. / 525, e7 = -1. / 40;
  double *k1 = malloc(nvar * sizeof(double)), *k2 = malloc(nvar * sizeof(double)), *k3 = malloc(nvar * sizeof(double)),
         *k4 = malloc(nvar * sizeof(double)), *k5 = malloc(nvar * sizeof(double)), *k6 = malloc(nvar * sizeof(double)),
         *k7 = malloc(nvar * sizeof(double)), *yt = malloc(nvar * sizeof(double)), *yn = malloc(nvar * sizeof(double));
  double t = 0, h = 1e-4, hcap = 0.05 / fmax(1.0, b / 2.0); long steps = 0, rejects = 0, si = 1;
  long nsamp = lround(end / dtout);
  emit(out, 0, y);
  while (si <= nsamp) {
    double target = si * dtout; if (si == nsamp) target = end;
    double hs = h; if (hs > hcap) hs = hcap; int land = 0; if (t + hs >= target - 1e-12) { hs = target - t; land = 1; }
    full(y, k1);
    for (int i = 0; i < nvar; i++) yt[i] = y[i] + hs * a21 * k1[i];
    full(yt, k2);
    for (int i = 0; i < nvar; i++) yt[i] = y[i] + hs * (a31 * k1[i] + a32 * k2[i]);
    full(yt, k3);
    for (int i = 0; i < nvar; i++) yt[i] = y[i] + hs * (a41 * k1[i] + a42 * k2[i] + a43 * k3[i]);
    full(yt, k4);
    for (int i = 0; i < nvar; i++) yt[i] = y[i] + hs * (a51 * k1[i] + a52 * k2[i] + a53 * k3[i] + a54 * k4[i]);
    full(yt, k5);
    for (int i = 0; i < nvar; i++) yt[i] = y[i] + hs * (a61 * k1[i] + a62 * k2[i] + a63 * k3[i] + a64 * k4[i] + a65 * k5[i]);
    full(yt, k6);
    for (int i = 0; i < nvar; i++) yn[i] = y[i] + hs * (b1 * k1[i] + b3 * k3[i] + b4 * k4[i] + b5 * k5[i] + b6 * k6[i]);
    full(yn, k7);
    double err = 0;
    for (int i = 0; i < nvar; i++) {
      double e = hs * (e1 * k1[i] + e3 * k3[i] + e4 * k4[i] + e5 * k5[i] + e6 * k6[i] + e7 * k7[i]);
      double sc = atol + rtol * fmax(fabs(y[i]), fabs(yn[i])); double r = fabs(e / sc); if (r > err) err = r;
    }
    if (!isfinite(err)) { fprintf(stderr, "nonfinite at %g\n", t); return 7; }
    double fac = err > 0 ? 0.9 * pow(err, -0.2) : 5; if (fac > 5) fac = 5; if (fac < 0.2) fac = 0.2;
    if (err <= 1) {
      memcpy(y, yn, nvar * sizeof(double)); t = land ? target : t + hs; steps++;
      if (land) { emit(out, t, y); si++; }
      if (!land || hs >= h) h = hs * fac; else h = fmax(h, hs * fac);
    } else { rejects++; h = hs * fac; }
    if (steps > 400000000L) return 8;
  }
  fclose(out);
  printf("END %ld %ld\n", steps, rejects);
  return 0;
}
